funkin_backend_scripting_Script.create = function(path) {
	if(openfl_utils_Assets.exists(path)) {
		switch(haxe_io_Path.extension(path).toLowerCase()) {
		case "hsc":case "hscript":case "hx":case "hxs":
			return new funkin_backend_scripting_HScript(path);
		case "lua":
			funkin_backend_system_Logs.trace("Lua is not supported in this engine. Use HScript instead.",2,12,null);
			return new funkin_backend_scripting_DummyScript(path);
		case "pack":
			var arr = openfl_utils_Assets.getText(path).split("________PACKSEP________");
			return funkin_backend_scripting_Script.fromString(arr[1],arr[0]);
		default:
			return new funkin_backend_scripting_DummyScript(path);
		}
	}
	return new funkin_backend_scripting_DummyScript(path);
};
funkin_backend_scripting_Script.fromString = function(code,path) {
	switch(haxe_io_Path.extension(path).toLowerCase()) {
	case "hsc":case "hscript":case "hx":case "hxs":
		return new funkin_backend_scripting_HScript(path).loadFromString(code);
	case "lua":
		funkin_backend_system_Logs.trace("Lua is not supported in this engine. Use HScript instead.",2,12,null);
		return new funkin_backend_scripting_DummyScript(path).loadFromString(code);
	default:
		return new funkin_backend_scripting_DummyScript(path).loadFromString(code);
	}
};
