			var c1 = _this.c * cos - _this.d * sin1;
			_this.d = _this.c * sin1 + _this.d * cos;
			_this.c = c1;
			var tx1 = _this.tx * cos - _this.ty * sin1;
			_this.ty = _this.tx * sin1 + _this.ty * cos;
