funkin_options_PlayerSettings.init = function() {
	if(funkin_options_PlayerSettings.solo == null) {
		funkin_options_PlayerSettings.solo = new funkin_options_PlayerSettings(0,funkin_backend_system_KeyboardScheme.Solo);
	}
	if(funkin_options_PlayerSettings.player1 == null) {
		funkin_options_PlayerSettings.player1 = new funkin_options_PlayerSettings(0,funkin_backend_system_KeyboardScheme.Duo(true));
		++funkin_options_PlayerSettings.numPlayers;
	}
	if(funkin_options_PlayerSettings.player2 == null) {
		funkin_options_PlayerSettings.player2 = new funkin_options_PlayerSettings(0,funkin_backend_system_KeyboardScheme.Duo(false));
		++funkin_options_PlayerSettings.numPlayers;
	}
	var numGamepads = flixel_FlxG.gamepads.get_numActiveGamepads();
	if(numGamepads > 0) {
		if(flixel_FlxG.gamepads._activeGamepads[0] == null) {
			throw haxe_Exception.thrown("Unexpected null gamepad. id:0");
		}
		funkin_options_PlayerSettings.player1.controls.addDefaultGamepad(0);
	}
	if(numGamepads > 1) {
		if(funkin_options_PlayerSettings.player2 == null) {
			funkin_options_PlayerSettings.player2 = new funkin_options_PlayerSettings(1,funkin_backend_system_KeyboardScheme.None);
			++funkin_options_PlayerSettings.numPlayers;
		}
		if(flixel_FlxG.gamepads._activeGamepads[1] == null) {
			throw haxe_Exception.thrown("Unexpected null gamepad. id:0");
		}
		funkin_options_PlayerSettings.player2.controls.addDefaultGamepad(1);
	}
};
