	parent: null
	,draw: function() {
		var i = 0;
		var menu;
		while(i < this.parent.treeLength) {
			menu = this.parent.tree[i++];
			if(menu == null || !menu.active || !menu.exists) {
				continue;
			}
			if(i == this.parent.treeLength || menu.persistentUpdate || menu.transitioning) {
				menu.draw();
			}
		}
		i = this.parent.previousMenus.length;
		while(i-- > 0) if(this.parent.previousMenus[i] != null) {
			this.parent.previousMenus[i].draw();
		}
	}
