				c1.x = c11.worldCOMx + nx1 * t1;
				c1.y = c11.worldCOMy + ny * t1;
				var t2 = -c21.radius;
				c2.x = c21.worldCOMx + nx1 * t2;
				c2.y = c21.worldCOMy + ny * t2;
