funkin_backend_system_console_BuiltInCommands.help = new funkin_backend_system_console_FuncCommand("help","[object]","(Shows full list of commands or list of fields on an object or class)",function(args) {
	if(args.length == 0) {
		var strBuf_b = "";
		strBuf_b = "\nCommands:";
		var _g = 0;
		var _g1 = funkin_backend_system_console_ConsoleCommandManager.commandsStringList;
		while(_g < _g1.length) {
			var cmd = funkin_backend_system_console_ConsoleCommandManager.getCommand(_g1[_g++]);
			strBuf_b += "\n\t";
			strBuf_b += Std.string(cmd.name);
			strBuf_b += " ";
			strBuf_b += Std.string(cmd.argsDesc);
			strBuf_b += "\n\t\t";
			strBuf_b += Std.string(cmd.desc);
		}
		funkin_backend_system_Logs.trace(strBuf_b,0,7,null);
	} else {
		var fields = funkin_backend_system_console_ConsoleUI.instance.consoleHscript.tryGetFields(args[0]);
		if(fields.length == 0) {
			funkin_backend_system_Logs.trace("Failed to find fields for: " + args[0],0,7,null);
			return;
		}
		var strBuf_b = "";
		strBuf_b = "\n";
		strBuf_b = "\n" + Std.string(args[0]);
		strBuf_b += ":";
		var _g = 0;
		while(_g < fields.length) {
			var f = fields[_g];
			++_g;
			strBuf_b += "\n\t";
			strBuf_b += Std.string(f.name);
			strBuf_b += ":";
			strBuf_b += Std.string(f.type);
			if(f.value != "") {
				strBuf_b += " = ";
				strBuf_b += Std.string(f.value);
			}
		}
		funkin_backend_system_Logs.trace(strBuf_b,0,7,null);
	}
});
