funkin_backend_system_console_BuiltInCommands.goToCharter = new funkin_backend_system_console_FuncCommand("goToCharter","[song] [diff] [variation]","(opens chart editor, inputting nothing will load existing song)",function(args) {
	if(args.length == 0) {
		if(funkin_game_PlayState.SONG == null) {
			funkin_backend_system_Logs.trace("Charter doesn't have any song data loaded!",2,12,null);
		} else if(funkin_editors_charter_Charter.__song == null || funkin_game_PlayState.SONG != null && funkin_game_PlayState.SONG.meta != null && funkin_game_PlayState.SONG.meta.name != funkin_editors_charter_Charter.__song || funkin_game_PlayState.difficulty != funkin_editors_charter_Charter.__diff || funkin_game_PlayState.variation != funkin_editors_charter_Charter.__variant) {
			var nextState = flixel_util_typeLimit_NextState.fromState(new funkin_editors_charter_Charter(funkin_game_PlayState.SONG.meta.name,funkin_game_PlayState.difficulty,funkin_game_PlayState.variation));
			var stateOnCall = flixel_FlxG.game._state;
			if(!((nextState) instanceof flixel_FlxState) || flixel_FlxG.canSwitchTo(nextState)) {
				flixel_FlxG.game._state.startOutro(function() {
					if(flixel_FlxG.game._state == stateOnCall) {
						flixel_FlxG.game._nextState = nextState;
					} else {
						flixel_FlxG.log.advanced("`onOutroComplete` was called after the state was switched. This will be ignored",flixel_system_debug_log_LogStyle.WARNING,true,{ fileName : "flixel/FlxG.hx", lineNumber : 408, className : "flixel.FlxG", methodName : "switchState"});
					}
				});
			}
		} else {
			var nextState1 = flixel_util_typeLimit_NextState.fromState(new funkin_editors_charter_Charter(funkin_editors_charter_Charter.__song,funkin_editors_charter_Charter.__diff,funkin_editors_charter_Charter.__variant,false));
			var stateOnCall1 = flixel_FlxG.game._state;
			if(!((nextState1) instanceof flixel_FlxState) || flixel_FlxG.canSwitchTo(nextState1)) {
				flixel_FlxG.game._state.startOutro(function() {
					if(flixel_FlxG.game._state == stateOnCall1) {
						flixel_FlxG.game._nextState = nextState1;
					} else {
						flixel_FlxG.log.advanced("`onOutroComplete` was called after the state was switched. This will be ignored",flixel_system_debug_log_LogStyle.WARNING,true,{ fileName : "flixel/FlxG.hx", lineNumber : 408, className : "flixel.FlxG", methodName : "switchState"});
					}
				});
			}
		}
		return;
	}
	var name = args[0];
	var diff = args[1];
	var variation = args[2] != null ? args[2] == "default" ? null : args[2] : null;
	var chartPath = funkin_backend_assets_Paths.chart(name,diff,variation);
	if(openfl_utils_Assets.exists(chartPath)) {
		var nextState2 = flixel_util_typeLimit_NextState.fromState(new funkin_editors_charter_Charter(name,diff,variation));
		var stateOnCall2 = flixel_FlxG.game._state;
		if(!((nextState2) instanceof flixel_FlxState) || flixel_FlxG.canSwitchTo(nextState2)) {
			flixel_FlxG.game._state.startOutro(function() {
				if(flixel_FlxG.game._state == stateOnCall2) {
					flixel_FlxG.game._nextState = nextState2;
				} else {
					flixel_FlxG.log.advanced("`onOutroComplete` was called after the state was switched. This will be ignored",flixel_system_debug_log_LogStyle.WARNING,true,{ fileName : "flixel/FlxG.hx", lineNumber : 408, className : "flixel.FlxG", methodName : "switchState"});
				}
			});
		}
	} else {
		funkin_backend_system_Logs.trace("Chart for song " + name + " at \"" + chartPath + "\" was not found.",2,12,null);
	}
});
